"""ClearSink controller. Uses only RGB-D, camera calibration and proprioception.
No simulator internals, demonstrations, policies, or resets.
Run as a persistent command worker; the executed commands are retained in commands.log.
"""
import os, sys, json, time, traceback
from pathlib import Path
import numpy as np
from scipy.spatial.transform import Rotation as Rot
from scipy.optimize import least_squares
from PIL import Image
from rcb_client import Robot
OUT=Path('/app/output'); CAMS=['robot0_agentview_center','robot0_agentview_left','robot0_agentview_right','robot0_eye_in_hand']
def trans(p=(0,0,0),r=(0,0,0)):
    T=np.eye(4);T[:3,:3]=Rot.from_euler('xyz',r).as_matrix();T[:3,3]=p;return T
ORIGINS=[trans((0,0,.333)),trans(r=(-np.pi/2,0,0)),trans((0,-.316,0),(np.pi/2,0,0)),trans((.0825,0,0),(np.pi/2,0,0)),trans((-.0825,.384,0),(-np.pi/2,0,0)),trans(r=(np.pi/2,0,0)),trans((.088,0,0),(np.pi/2,0,0))]
def fk(q):
    T=np.eye(4)
    for a,o in zip(q,ORIGINS):T=T@o@trans(r=(0,0,a))
    return T
class Controller:
    def __init__(self):
        self.r=Robot();self.i=0;self.obs=self.r.get_obs(include_depth=True,video='none');self.update(self.obs,'start');self.samples=[];self.model=None
    def update(self,o,name):
        self.obs=o;self.p=np.array(o.meta['proprio']['now']);self.q=self.p[4:11];self.eef=self.p[26:29];self.cmd=self.p[29:42].copy();self.i+=1
        self.folder=OUT/f'{self.i:03d}_{name}';o.save(str(self.folder));
        (OUT/'latest.json').write_text(json.dumps({'folder':str(self.folder),'q':self.q.tolist(),'eef':self.eef.tolist(),'fingers':self.p[11:13].tolist(),'time_left_s':o.meta['time_left_s']}))
        print(json.dumps({'folder':str(self.folder),'q':self.q.tolist(),'eef':self.eef.tolist(),'fingers':self.p[11:13].tolist(),'time_left_s':o.meta['time_left_s']}),flush=True)
    def observe(self,name='observe'):
        self.update(self.r.get_obs(include_depth=True,video='none'),name)
    def joints(self,q,seconds=2,grip=None,name='joints',base=None,torso=0,mode=-1):
        n=max(1,int(seconds/.05));A=np.tile(self.cmd,(n,1));A[:,:7]=np.linspace(self.q,q,n);A[:,8:12]=0;A[:,12]=mode
        if grip is not None:A[:,7]=grip
        if base is not None:A[:,8:11]=base
        A[:,11]=torso
        self.update(self.r.submit('joint_position',A,cameras=CAMS,include_depth=True,video='none',note=name),name)
    def sample(self):
        C=np.array(self.obs.meta['cameras'][CAMS[-1]]['cam2world_gl']);self.samples.append({'q':self.q.tolist(),'eef':self.eef.tolist(),'cam':C.tolist()})
        (OUT/'calibration.json').write_text(json.dumps(self.samples,indent=2))
    def calibrate(self):
        q0=self.q.copy();self.sample()
        for j in range(7):
            q=q0.copy();q[j]+=.09;self.joints(q,1.3,name=f'calib{j}');self.sample()
        self.joints(q0,1.3,name='calib_return');self.fit()
    def fit(self):
        qs=[fk(s['q']) for s in self.samples];ps=np.array([s['eef'] for s in self.samples]);cs=[np.array(s['cam']) for s in self.samples]
        # Camera orientation change is a rigid measurement of the wrist rotation.
        def residual(x):
            R=Rot.from_rotvec(x[:3]).as_matrix();t=x[3:6];off=x[6:9];Rc=Rot.from_rotvec(x[9:12]).as_matrix()
            return np.r_[np.concatenate([R@F[:3,:3]@off+R@F[:3,3]+t-p for F,p in zip(qs,ps)]),np.concatenate([(.2*(R@F[:3,:3]@Rc-C[:3,:3])).ravel() for F,C in zip(qs,cs)])]
        x=np.r_[0,0,np.pi/2,4.2,-.9,.4,0,0,.204,0,0,0]
        fit=least_squares(residual,x,max_nfev=2000,ftol=1e-12,gtol=1e-12,xtol=1e-12)
        self.model=fit.x;print('MODEL',fit.x,'residual',np.linalg.norm(fit.fun),flush=True);np.save(OUT/'model.npy',self.model)
    def pose(self,q):
        F=fk(q);x=self.model;R=Rot.from_rotvec(x[:3]).as_matrix();return R@(F[:3,3]+F[:3,:3]@x[6:9])+x[3:6],R@F[:3,:3]@Rot.from_rotvec(x[9:12]).as_matrix()
    def ik(self,p,R=None,q0=None):
        q0=self.q.copy() if q0 is None else q0
        def err(q):
            pp,rr=self.pose(q);e=(pp-p)*5
            if R is not None:e=np.r_[e,Rot.from_matrix(R@rr.T).as_rotvec()*.5]
            return np.r_[e,.005*(q-q0)]
        fit=least_squares(err,q0,bounds=([-2.89,-1.76,-2.89,-3.06,-2.89,-.01,-2.89],[2.89,1.76,2.89,-.07,2.89,3.75,2.89]),max_nfev=400)
        pp,rr=self.pose(fit.x);print('IK',np.round(pp,4), 'err',np.round(pp-p,4),'q',np.round(fit.x,4),flush=True)
        if np.linalg.norm(pp-p)>.025:raise ValueError('Unreachable target')
        return fit.x
    def move(self,p,R=None,seconds=2,grip=None,name='move',steps=1):
        p=np.array(p);start=self.eef.copy()
        for k in range(steps):
            dest=start+(p-start)*(k+1)/steps; q=self.ik(dest,R);self.joints(q,seconds/steps,grip,name+str(k))
    def point(self,cam,u,v):
        if cam not in CAMS:cam='robot0_'+cam
        d=self.obs.depth[cam];d=d[-1] if d.ndim==3 else d;z=float(d[int(v),int(u)]);K=np.array(self.obs.meta['cameras'][cam]['intrinsic_cv']);C=np.array(self.obs.meta['cameras'][cam]['cam2world_gl']);return C[:3,:3]@np.array([(u-K[0,2])*z/K[0,0],-(v-K[1,2])*z/K[1,1],-z])+C[:3,3]
    def grip(self,val,seconds=1,name='grip'):self.joints(self.q,seconds,grip=val,name=name)

def worker():
    c=Controller();ns={'c':c,'np':np,'Rot':Rot,'OUT':OUT}
    print('READY',flush=True)
    while True:
        req=OUT/'request.py'
        if req.exists():
            src=req.read_text();req.unlink()
            with (OUT/'commands.log').open('a') as f:f.write(src+'\n')
            try:exec(compile(src,'request.py','exec'),ns)
            except Exception:traceback.print_exc()
            print('DONE',flush=True)
            (OUT/'done').write_text(str(time.time()))
        time.sleep(.2)
if __name__=='__main__':worker()
PY
